def minFlips(a: int, b: int, c: int) -> int:
    flips = 0

    while a or b or c:
        bit_a = a & 1
        bit_b = b & 1
        bit_c = c & 1

        if bit_c == 0:
            # Both a and b must be 0. If any is 1, must flip each 1 to 0.
            if bit_a == 1:
                flips += 1
            if bit_b == 1:
                flips += 1
        else:
            # At least one of a or b must be 1. If both are 0, flip one to 1.
            if bit_a == 0 and bit_b == 0:
                flips += 1

        a >>= 1
        b >>= 1
        c >>= 1

    return flips
